package org.example;
import java.util.*;
public class BookstoreService { private final AccountService accounts=new AccountService(); private final List<Item> catalog=new ArrayList<>(); private final Map<Integer,List<Order>> orders=new HashMap<>(); private int orderId=50001,paymentId=80001;
 public BookstoreService(){catalog.add(new PrintedBook(101,"Java Programming",150,"Herbert Schildt",10,1.2,"A practical introduction to Java."));catalog.add(new Ebook(102,"Clean Code (PDF)",89.99,"Robert C. Martin","PDF",4.5,"A guide to readable code."));catalog.add(new Magazine(103,"Tech Monthly",25.50,"Editorial Team","Vol. 12","October",2026,"Tech Monthly Press","Technology news and ideas."));catalog.add(new PrintedBook(104,"The Pragmatic Programmer",499,"David Thomas",6,.8,"Practical advice for developers."));catalog.add(new Ebook(105,"Algorithms Made Simple",119,"A. Rivera","EPUB",2.1,"A beginner-friendly algorithms guide."));catalog.add(new Magazine(106,"Science & Discovery",75,"Science Desk","Issue 08","September",2026,"Discovery Media","Science and discovery."));}
 public Customer signUp(String n,String e,String p,String a){return accounts.signUp(n,e,p,a);} public Customer signIn(String e,String p){return accounts.signIn(e,p);} public List<Item> getCatalog(){return List.copyOf(catalog);} public Order createOrder(Customer c){return new Order(orderId++,c);} public List<Order> getOrders(Customer c){return List.copyOf(orders.getOrDefault(c.getCustomerID(),List.of()));} public void checkout(Order o,String method){o.setPayment(PaymentFactory.create(method,paymentId++));o.checkout();orders.computeIfAbsent(o.getCustomer().getCustomerID(),k->new ArrayList<>()).add(o);}
}